<?php $title='Cari Informasi | '.($settings['site_name']??'Sukamulya');$this->load->view('site/header',compact('title','settings','menu')); ?><main><section class="page-title"><div class="wrap"><h1>Cari Informasi</h1><form class="search-page" action="<?= site_url('cari') ?>" method="get"><input name="q" value="<?= html_escape($query) ?>" placeholder="Cari pengumuman, agenda, atau halaman"><button class="button" type="submit">Cari</button></form></div></section><section class="section"><div class="wrap"><?php if(mb_strlen($query)<2): ?><p>Masukkan minimal 2 karakter.</p><?php elseif(!$pages&&!$posts): ?><p>Tidak ada hasil untuk “<?= html_escape($query) ?>”.</p><?php endif; ?><?php foreach($pages as $page): ?><p><a href="<?= site_url('halaman/'.$page['slug']) ?>"><?= html_escape($page['title']) ?></a> · Halaman</p><?php endforeach; ?><?php foreach($posts as $post): ?><p><a href="<?= site_url($post['type']) ?>"><?= html_escape($post['title']) ?></a> · <?= html_escape(ucfirst($post['type'])) ?></p><?php endforeach; ?></div></section></main><?php $this->load->view('site/footer',compact('settings')); ?>
